CREATE TABLE IF NOT EXISTS `dpn_medical_surgeries` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`surgeon_cid` varchar(64) NOT NULL,`procedure_id` varchar(64) NOT NULL,`body_part` varchar(32) NULL,`status` varchar(32) NOT NULL,`details` longtext NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_surgery_patient` (`patient_cid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
